def parse_price(s: str) -> float:
    import re
    match = re.match(r'^\$?([0-9,]+)\.?([0-9]*)$', s)
    if not match:
        raise ValueError(f"Invalid price format: {s}")
    dollars, cents = match.groups()
    dollars = dollars.replace(',', '')
